// src/battle/engine/commands/CommandResult.ts
function ok() {
  return { ok: true };
}
function reject(reason) {
  return { ok: false, reason };
}
function accepted(next, events = []) {
  return { ok: true, state: next, events };
}
function rejected(state, reason, events = []) {
  return { ok: false, state, reason, events };
}

