var GBC_FPS = GAMEPLAY_CONFIG.gbcNativeFps;
var COUNTER_WINDOW_TICKS = 30;
var STAGE_PREP_TICKS = 60;
var STAGE_PREP_BEATS = [
  { frame: 0, pose: "stage_ready_idle" },
  // espera inicial
  { frame: 12, pose: "stage_ready_open" },
  // estira brazos (asset INFERRED: gather_power)
  { frame: 30, pose: "stage_ready_close" },
  // encoge brazos (asset INFERRED: beam_charge)
  { frame: 48, pose: "stage_ready_idle" }
  // último idle → INPUT_OPEN (60)
];
function advanceBattleClock(state, ticks) {
  const n = Math.floor(ticks);
  if (!(n > 0)) return { state, events: [], eventTicks: [] };
  let s = state;
  const events = [];
  const eventTicks = [];
  let remaining = n;
  while (remaining > 0) {
    const q = s.stageQte;
    const activeDeadline = q.state === "PREPARING" ? q.inputOpenTick : q.state === "INPUT_WINDOW" ? q.deadlineTick : q.state === "COUNTER_WINDOW" ? q.counterDeadlineTick : 0;
    const sw = s.pendingCharacterSwitch;
    if (activeDeadline <= 0 && !sw) {
      s = { ...s, tick: s.tick + remaining };
      remaining = 0;
      break;
    }
    const nextTick = s.tick + 1;
    s = { ...s, tick: nextTick };
    remaining -= 1;
    const q2 = s.stageQte;
    if (q2.state === "PREPARING" && nextTick >= q2.inputOpenTick) {
      const level = q2.seq.length >= 4 ? q2.seq.length >= 5 ? 5 : 4 : 3;
      s = {
        ...s,
        stageQte: {
          ...q2,
          state: "INPUT_WINDOW",
          startedTick: nextTick,
          deadlineTick: nextTick + q2.windowTicks
        }
      };
      events.push({ type: "QTE_STARTED", side: "player", level, seq: q2.seq, limitFrames: q2.windowTicks });
      eventTicks.push(nextTick);
    } else if (q2.state === "INPUT_WINDOW" && nextTick >= q2.deadlineTick) {
      s = {
        ...s,
        stageQte: {
          ...q2,
          state: "COUNTER_WINDOW",
          counterStartTick: nextTick,
          counterDeadlineTick: nextTick + COUNTER_WINDOW_TICKS
        }
      };
      events.push({ type: "QTE_TIMEOUT", side: "player", window: "INPUT" });
      events.push({ type: "QTE_COUNTER_STARTED", side: "player" });
      eventTicks.push(nextTick, nextTick);
    } else if (q2.state === "COUNTER_WINDOW" && nextTick >= q2.counterDeadlineTick) {
      const card = q2.card ?? resolveStageCard(s, q2.seq.length);
      const counter = resolveCounterDamage(s, card.type);
      s = {
        ...counter.state,
        stageQte: { ...counter.state.stageQte, state: "WAITING" }
      };
      const ticks2 = counter.events.map(() => nextTick);
      events.push(...counter.events, { type: "QTE_COUNTER_RESOLVED", side: "enemy", action: "TIMEOUT" });
      eventTicks.push(...ticks2, nextTick);
    }
    if (sw) {
      if (nextTick >= sw.completedTick) {
        events.push({ type: "CHARACTER_SWITCH_COMPLETED", side: sw.side });
        eventTicks.push(nextTick);
        s = { ...s, pendingCharacterSwitch: null };
      } else if (nextTick >= sw.commitTick) {
        const sideFighter = sw.side === "player" ? s.player : s.enemy;
        const sideReserve = sw.side === "player" ? s.player2 : s.enemy2;
        if (sideReserve) {
          const alt = POSITION_DATA[sideReserve.battlePos].altitude;
          const newPos = alt === "AIR" ? "UP_BACK" /* UP_BACK */ : "DOWN_BACK" /* DOWN_BACK */;
          const switchedActive = { ...sideReserve, battlePos: newPos, powerWindowCounter: 2 };
          s = sw.side === "player" ? { ...s, player: switchedActive, player2: sideFighter } : { ...s, enemy: switchedActive, enemy2: sideFighter };
        }
        events.push({ type: "CHARACTER_SWITCH_COMMITTED", side: sw.side });
        eventTicks.push(nextTick);
        s = { ...s, pendingCharacterSwitch: { ...sw, commitTick: Number.POSITIVE_INFINITY } };
      }
    }
  }
  return { state: s, events, eventTicks };
}

// src/battle/engine/commands/reducers/resourceReducer.ts
function payCc(state, side, cost) {
  if (cost <= 0) return { state, events: [] };
  const fighter = side === "player" ? state.player : state.enemy;
  const before = fighter.cc;
  const after = Math.max(0, before - cost);
  const amount = before - after;
  if (amount <= 0) return { state, events: [] };
  const nextFighter = { ...fighter, cc: after };
  return {
    state: {
      ...state,
      player: side === "player" ? nextFighter : state.player,
      enemy: side === "enemy" ? nextFighter : state.enemy
    },
    events: [{ type: "CC_SPENT", side, amount, before, after }]
  };
}
function gainCc(state, side, amount) {
  if (amount <= 0) return { state, events: [] };
  const fighter = side === "player" ? state.player : state.enemy;
  const before = fighter.cc;
  const after = Math.min(fighter.maxCc, before + amount);
  const gained = after - before;
  if (gained <= 0) return { state, events: [] };
  const nextFighter = { ...fighter, cc: after };
  return {
    state: {
      ...state,
      player: side === "player" ? nextFighter : state.player,
      enemy: side === "enemy" ? nextFighter : state.enemy
    },
    events: [{ type: "CC_GAINED", side, amount: gained, before, after }]
  };
}

// src/battle/engine/commands/reducers/cardReducer.ts
function removeFromHand(state, side, handIndex) {
  const deck2 = side === "player" ? state.deck : state.eDeck;
  const card = deck2.hand[handIndex];
  if (!card) return { state, card: null };
  const hand = deck2.hand.filter((_, i) => i !== handIndex);
  const nextDeck = {
    ...deck2,
    hand,
    discardPile: [...deck2.discardPile, card]
  };
  return {
    state: {
      ...state,
      deck: side === "player" ? nextDeck : state.deck,
      eDeck: side === "enemy" ? nextDeck : state.eDeck
    },
    card
  };
}
function playCard(state, side, handIndex) {
  const deck2 = side === "player" ? state.deck : state.eDeck;
  const card = deck2.hand[handIndex];
  const cost = card?.cc ?? 0;
  const paid = payCc(state, side, cost);
  const moved = removeFromHand(paid.state, side, handIndex);
  const cardId = moved.card?.id ?? (card?.id ?? -1);
  const events = [
    ...paid.events,
    ...cardId >= 0 ? [
      { type: "CARD_PLAYED", side, cardId },
      { type: "CARD_DISCARDED", side, cardId }
    ] : []
  ];
  return { state: moved.state, events, cardId };
}
function playLimitCard(state, side, cardId) {
  const catalog = getCard(cardId);
  const card = state.limits.includes(cardId) && catalog ? { id: cardId, cc: catalog.cc } : null;
  const cost = card?.cc ?? 0;
  const paid = payCc(state, side, cost);
  const events = [
    ...paid.events,
    ...cardId >= 0 ? [{ type: "CARD_PLAYED", side, cardId }] : []
  ];
  return { state: paid.state, events, cardId };
}
function playDefenseCard(state, side, handIndex) {
  const deck2 = side === "player" ? state.deck : state.eDeck;
  const card = deck2.hand[handIndex];
  const cost = card?.cc ?? 0;
  const paid = payCc(state, side, cost);
  const moved = removeFromHand(paid.state, side, handIndex);
  const cardId = moved.card?.id ?? (card?.id ?? -1);
  const events = [
    ...paid.events,
    ...cardId >= 0 ? [
      { type: "CARD_PLAYED", side, cardId },
      { type: "CARD_DISCARDED", side, cardId }
    ] : []
  ];
  return { state: moved.state, events, cardId };
}

