// src/battle/engine/commands/reducers/powerReducer.ts
function powerStateFromCounter(counter) {
  return counter > 0 ? "FULL_POWER" : "NORMAL";
}
function decrementPowerWindow(state, side) {
  const fighter = side === "player" ? state.player : state.enemy;
  if (fighter.powerWindowCounter <= 0) return { state, events: [] };
  const to = fighter.powerWindowCounter - 1;
  const next = { ...fighter, powerWindowCounter: to };
  return {
    state: side === "player" ? { ...state, player: next } : { ...state, enemy: next },
    events: [
      { type: "POWER_CHANGED", from: powerStateFromCounter(fighter.powerWindowCounter), to: powerStateFromCounter(to) }
    ]
  };
}
function postActionMaintenance(state) {
  const p = decrementPowerWindow(state, "player");
  const e = decrementPowerWindow(p.state, "enemy");
  const events = [...p.events, ...e.events];
  if (events.length === 0) return { state, events: [] };
  const decremented = [];
  if (p.events.length > 0) decremented.push("player");
  if (e.events.length > 0) decremented.push("enemy");
  return {
    state: e.state,
    events: [{ type: "POST_ACTION_MAINTENANCE", decrementedPowerWindows: decremented }, ...events]
  };
}
function gatherPower(state, side) {
  if (side !== "player") return { state, events: [] };
  const from = powerStateFromCounter(state.player.powerWindowCounter);
  const to = "FULL_POWER";
  return {
    state: {
      ...state,
      player: { ...state.player, powerWindowCounter: 5 }
    },
    events: [
      { type: "GATHER_STARTED", side, mode: to },
      { type: "POWER_CHANGED", from, to }
    ]
  };
}
function characterSwitchPowerWindow(state, side) {
  return {
    state: {
      ...state,
      pendingCharacterSwitch: {
        side,
        commitTick: state.tick + CHARA_SWITCH_COMMIT_OFFSET,
        completedTick: state.tick + CHARA_SWITCH_COMPLETED_OFFSET
      }
    },
    events: [
      { type: "CHARACTER_SWITCH_STARTED", side }
    ]
  };
}
function guard(state, side) {
  if (side !== "player") return { state, events: [] };
  return {
    state: { ...state, playerGuard: "reduce" },
    events: [{ type: "GUARD_STARTED", side, guard: "reduce" }]
  };
}
function qteCorrectInput(state, side, input) {
  const q = state.stageQte;
  const indexBefore = q.idx;
  const nextIdx = q.idx + 1;
  const withCc = gainCc(state, side, 1);
  const completed = nextIdx >= q.seq.length;
  const nextQte = completed ? { ...q, idx: nextIdx, correct: q.correct + 1, state: "COMPLETED", result: "FULL_SUCCESS" } : { ...q, idx: nextIdx, correct: q.correct + 1 };
  const events = [
    ...withCc.events,
    { type: "QTE_INPUT_RESOLVED", side, input, success: true, indexBefore, indexAfter: nextIdx },
    ...completed ? [{ type: "QTE_COMPLETED", side, correct: q.correct + 1 + q.repaired, total: q.seq.length, result: "FULL_SUCCESS" }] : []
  ];
  return { state: { ...withCc.state, stageQte: nextQte }, events, completed, failed: false };
}
function qteWrongInput(state, side, input) {
  const q = state.stageQte;
  const nextIdx = q.idx + 1;
  const nextQte = {
    ...q,
    idx: nextIdx,
    state: "COUNTER_WINDOW",
    counterStartTick: state.tick,
    counterDeadlineTick: state.tick + COUNTER_WINDOW_TICKS
  };
  return {
    state: { ...state, stageQte: nextQte },
    events: [
      { type: "QTE_INPUT_RESOLVED", side, input, success: false, indexBefore: q.idx, indexAfter: nextIdx },
      { type: "QTE_FAILED", side, input },
      { type: "QTE_COUNTER_STARTED", side }
    ],
    completed: false,
    failed: true
  };
}
function qteCounterDefend(state, side) {
  return {
    state: {
      ...state,
      playerGuard: side === "player" ? "reduce" : state.playerGuard,
      stageQte: { ...state.stageQte, state: "WAITING", counterDeadlineTick: 0 }
    },
    events: [
      { type: "QTE_COUNTER_RESOLVED", side, action: "DEFEND" },
      ...side === "player" ? [{ type: "GUARD_STARTED", side, guard: "reduce" }] : []
    ]
  };
}
function qteCounterContinue(state, side) {
  const q = state.stageQte;
  const withCc = gainCc(state, side, 1);
  return {
    state: {
      ...withCc.state,
      stageQte: {
        ...q,
        repaired: q.repaired + 1,
        state: "INPUT_WINDOW",
        // M8.D — el deadline GLOBAL de la secuencia NO se reinicia (ROM §7:
        // single global timer). La reparación devuelve a la ventana de inputs
        // con el deadline original; si este ya expiró durante la recuperación,
        // el reloj cerrará la ventana en el siguiente tick (timeout).
        deadlineTick: q.deadlineTick,
        counterStartTick: 0,
        counterDeadlineTick: 0
      }
    },
    events: [{ type: "QTE_COUNTER_RESOLVED", side, action: "CONTINUE" }]
  };
}

