function manifestForms() {
  return [...new Set(MANIFEST_FRAME_INDEX.map((frame) => frame.formId))].sort();
}
function manifestFramesFor(formId, pose) {
  return MANIFEST_FRAME_INDEX.filter((frame) => frame.formId === formId && frame.pose === pose).sort((a, b2) => a.index - b2.index);
}
function manifestFrame(formId, pose, index) {
  return manifestFramesFor(formId, pose)[index];
}
function manifestFileUsage(formId, file) {
  return MANIFEST_FRAME_INDEX.filter((frame) => frame.formId === formId && frame.file === file);
}

