      id: "NO_ROM_PRESENTATION_PROGRAM",
      kind: "NONE",
      tick: null,
      durationTicks: null,
      macroId: null,
      resource: null,
      fxResource: null,
      palette: null,
      frame: null,
      motion: null,
      branchFamily: null,
